    scramble: {
        type: "exchange",
        exec: async function ({strikeLogic, potentialTargets, targetTile, data}) {

            let tiles = potentialTargets.map(t=>t.piece.tile)
            for (let tile of tiles) { 
                if(tile != targetTile || data?.tinyMode) tile.classList.add('minorfx')
                else if(data?.bigMode) tile.classList.add('bigscramblefx')
                tile.classList.add('scramblefx') 
                
            }
            await wait(200)
            if(strikeLogic) strikeLogic()

            env.setTimeout(() => {
                for (let tile of tiles) {
                    tile.classList.remove('scramblefx', 'minorfx', 'bigscramblefx')
                }
            }, 1000)
            
            await wait(1300)
        }
    },

