    miltza_attack: {
        slug: "miltza_attack",
        name: "Advantage",
        type: 'target',
        anim: "basic-attack",
        sceneAnim: "distractionsnipe",
        
        usage: {
            act: "%USER claws at %TARGET",
            crit: "A FRIGHTENING BLOW",
            hit: "%TARGET is struck",
            miss: "%TARGET EVADES"
        },

        details: {
            flavor: "'a three-armed assault';'carefully planned'",
            onUse: () => `'reuse this action twice on random vulnerable foes${env?.rpg?.is2D ? ' in range' : ''}'`,
            onHit: `'[STAT::amt]'${env?.rpg?.is2D ? `;'[STAT::kb]'` : ''}`,
            onCrit:`'[STATUS::vulnerable]'`,
            conditional: () => env?.rpg?.is2D ? `<em>ADVANTAGE::</em>'[STATUS::evasion] to nearby allies if all 3 hits are successful'` : `<em>ADVANTAGE::</em>'[STATUS::evasion] to team if all <n-col class="shiftdetail">(targetable and alive)</n-col> foes are [STATUS::vulnerableRef]'`
        },

        aoe: {
            size: 0,
        },

        stats: {
            accuracy: 1,
            crit: 0.15,
            amt: 1,
            range: 2,
            kb: 1,
            status: {
                evasion: {
                    name: 'evasion',
                    length: 1
                },
                vulnerableRef: { name: 'vulnerable'},
                vulnerable: {
                    name: 'vulnerable',
                    length: 1
                }
            },

            extraAOE: {
                evasionAura: {
                    origin: "self",
                    size: 3,
                    shape: 'square',
                    addClass: "beneficial" // added to tiles when displaying range
                }
            }
        },

        exec: function(user, target, beingUsedAsync, {actionMessageIndex, reason} = {}) {
            let action = this

            //special bonus only applies on first use
            if(reason != "plan" && !env.rpg.is2D) if(user.enemyTeam.members.every((m)=>
                //everyone targetable must be vulnerable
                hasStatus(m, "vulnerable") || (m.untargetable || m.state != "living")
            )) {
                env.GENERIC_ACTIONS.teamWave({
                    team: user.team,
                    exec: (actor, i)=>{
                        addStatus({target: actor, origin: user, status: "evasion", length: 1})
                    }
                })
            }

            return env.GENERIC_ACTIONS.singleTarget({
                action, 
                user, 
                target,

                critExec: ({target})=> {
                    addStatus({target: target, status: "vulnerable", length: 2});
                },

                hitExec: ({target}) => {
                    if(env?.rpg?.is2D) {
                        if(target.piece && user.piece) target.piece.knockback({
                            direction: user?.piece?.tile.getRelativeDirection(target?.piece?.tile), 
                            strength: 1
                        })
                    }
                },

                genExec: () => {
                    if(reason != "plan") { 
                        env.rpg.turnData[`${user.slug}_${actionMessageIndex}_advantageHits`] = 0
                        for (let i = 0; i < 2; i++) {
                            setTimeout(() => {
                                let targetList
                                if(env.rpg.is2D) {
                                    targetList = env.rpg.grid.getAoETargets({
                                        tile: user?.piece?.tile, 
                                        actor: user,
                                        actingOn: "nonallies",
                                        aoeData: {
                                            size: 2
                                        }
                                    })

                                    //if the targetList has a slug with 'destructible' in it, we only attack those if there's no true enemies
                                    if(targetList.some(t=>t.slug.includes("destructible")) && !targetList.some(t=>t.team.name != user.team.name && t.state == "living" && !t.untargetable)) {
                                        targetList = targetList.filter(t=>t.slug.includes("destructible"))
                                    }
                                } else {
                                    targetList = user.enemyTeam.members
                                }

                                let target = targetList.filter(m=>
                                    hasStatus(m, "vulnerable") &&
                                    !(// can't be any of these
                                        m.untargetable ||
                                        m.state != "living"
                                    )
                                ).sample()

                                if(target) {
                                    let hit = useAction(user, this, target, {beingUsedAsync: true, reason: "plan", actionMessageIndex, triggerActionUseEvent: false}) // kuvi was here

                                    //rewriting to be sequential would kinda suck so we just have the animations be sliiiightly slow
                                    if(env.rpg?.is2D) env.rpg.grid.handleAnim('distractionsnipe', () => {}, {origin: user, target, action: this})

                                    if(hit) {env.rpg.turnData[`${user.slug}_${actionMessageIndex}_advantageHits`]++}
                                    if(env.rpg.is2D && env.rpg.turnData[`${user.slug}_${actionMessageIndex}_advantageHits`] === 2) {
                                        let alliesNear = env.rpg.grid.getAoETargets({
                                            tile: user?.piece?.tile, 
                                            actor: user,
                                            actingOn: "allies",
                                            aoeData: {
                                                size: this.stats.extraAOE.evasionAura.size,
                                                shape: this.stats.extraAOE.evasionAura.shape
                                            }
                                        })
                                        
                                        env.GENERIC_ACTIONS.teamWave({
                                            arbitraryActorList: alliesNear,
                                            exec: (actor, i)=>{
                                                addStatus({target: actor, origin: user, status: "evasion", length: 1})
                                            }
                                        })
                                    }
                                }
                            }, (env.ADVANCE_RATE * 0.5) - (env.ADVANCE_RATE * 0.1) * (i + 1)) 
                        }
                    }
                }
            })
        }
    },

