    special_split_advancer: {
        slug: "special_split_advancer",
        name: "Flood",
        type: 'special+autohit+self',
        anim: "heal",
        usage: {
            act: "the distortion grows closer...",
        },
        autohit: true,

        details: {
            flavor: `'divert attention from the ceremony';'seize this opportunity to halt the misguided'`,
            onUse: `'press forward and <o-col>DISTORT</o-col> tiles based on distance';'conjure allies to strike'`,
            conditional: "<em><o-col>GRASPING DISTORTION::</o-col></em>'[STAT::amt] [STAT::kb] towards distortion'"
        },

        stats: {
            autohit: true,
            amt: 1,
            kb: 2
        },

        strings: {
            telegraphName: "Imminent Claw",
            telegraphHelp: "Something prepares to grasp this space...",
        },

        exec: function(user, target, beingUsedAsync, {actionMessageIndex}) {
            user.piece.focusOnTile()

            //scale based on distance from closest ally team member
            let closestAlly = user.piece.getActorDistance({actors: env.rpg.allyTeam.members}).sort((a,b)=>a.distance - b.distance)[0]
            let dist = closestAlly ? closestAlly.pathDistance : 0

            user.piece.knockback({
                direction: "up",
                strength: dist > 9 ? 3 : ((dist > 6) || env.rpg.wallsKilled == 2 ? 2 : 1),
                ignoreMods: true,
                falloff: false
            })

            play("scarydoia")

            let tiles
            setTimeout(() => {   
                tiles = env.rpg.grid.markTiles({
                    originTile: user.piece.tile,
                    shape: "custom",
                    customShape: `
                        xxxxx
                        xxoxx
                        xxxxx
                        xxxxx
                    `,
                    direction: "up",
                    includesOrigin: true,
                })

                env.rpg.grid.handleAnim('scramble', () => {
                    play("dull", 0.75)
                    if(!user.advancerEffect) {
                        user.advancerEffect = env.rpg.grid.createTileEffect({
                            tiles, 
                            effect: "clawing_distortion", 
                            length: 300, 
                            origin: user,
                            originTile: user.piece.tile
                        })
                    } else {
                        tiles.forEach(tile=>tile.addToEffect(user.advancerEffect, {length: 300, addingBy: "creation"}))
                    }

                    tiles.forEach(tile=>tile.classList.add('notile', 'damagetile'))
                    if(env.rpg.scenario.name == "ep4_vek_pt5_ing") {
                        let amt = 2
                        for(let i = 0; i < amt; i++) {
                            let spawnTile = tiles.filter(tile=>!tile.piece).sample()
                            if(spawnTile) midCombatActorAdd(env.rpg.enemyTeam, "arch_formless", "left", {location: "specificTile", specificTile: spawnTile})                    
                        }
                    }
                }, {targetTile: user.piece.tile, potentialTargets: [user], data: {bigMode: true}})
            }, env.ADVANCE_RATE)

            // starts randomly clawing ahead
            let advanceMult = 0
            if((env.rpg.wallsKilled && user.advancerEffect) || (user.advancerEffect && env.rpg.scenario.name == "ep4_vek_pt5_ing")) {
                advanceMult += 1.5
                setTimeout(() => {
                    env.rpg.effectMessage.action({
                        user: user,
                        target: user,
                        action: `the distortion grows closer...`,
                        specialHitText: `the presence prepares to lunge forward...`,
                        showFullDetail: true,
                        isMinor: true,
                        actionMessageIndex
                    })

                    /*
                    let attackTiles = env.rpg.grid.markTiles({
                        originTile: user.piece.tile,
                        shape: "custom",
                        customShape: `
                            xxxxx
                            xxxxx     
                            xxxxx
                            xxxxx
                            xxxxx
                            xxxxx
                            xxxxx
                            xxxxx
                            xxxxx
                            xxxxx
                            xxxxx
                            xxxxx
                            xxxxx
                            .....
                            ..o..
                        `,
                        direction: "up",
                    })

                    attackTiles = attackTiles.filter(t=> !t.hasEffect("clawing_distortion"))
                    let tilesToHit = []
                    let amt = dist > 6 ? 10 : 4
                    for(let i = 0; i < amt; i++) {
                        if(attackTiles.length) tilesToHit.push(attackTiles.sample({remove: true}))
                    }

                    let effect = env.rpg.grid.createTileEffect({
                        tiles: tilesToHit, 
                        effect: "telegraph",
                        telegraphExec: (telEffect) => {
                            play("laser")
                            telEffect.tiles.forEach(tile=>{
                                tile.addToEffect(user.advancerEffect, {length: 300, addingBy: "creation"})
                                tile.classList.add("notile")
                            })
                        },
                        telegraphAnim: "archtelegraph",
                        length: 1,
                        origin: user,
                        specialName: this.strings.telegraphName,
                        specialHelp: this.strings.telegraphHelp
                    })
                    */
                    
                    play("scarydoia", 1.25)
                    env.rpg.eyebeamOrigin = user
                    env.rpg.aimingDirection = "up"
                    let spawnTiles = tiles.filter(t => !t.piece && !t.blocking)
                    if(spawnTiles.length) midCombatActorAdd(env.rpg.neutralTeam, "finale_eyebeam", "right", {location: "specificTile", specificTile: spawnTiles.sample({remove: true})})
                    if(spawnTiles.length) midCombatActorAdd(env.rpg.neutralTeam, "finale_eyebeam", "right", {location: "specificTile", specificTile: spawnTiles.sample({remove: true})})
                    if(dist > 10 && spawnTiles.length) midCombatActorAdd(env.rpg.neutralTeam, "finale_eyebeam", "right", {location: "specificTile", specificTile: spawnTiles.sample({remove: true})})
                    if(dist > 10 && spawnTiles.length) midCombatActorAdd(env.rpg.neutralTeam, "finale_eyebeam", "right", {location: "specificTile", specificTile: spawnTiles.sample({remove: true})})
                }, env.ADVANCE_RATE * 3)
            }
            
            setTimeout(() => {
                advanceTurn(user)                
            }, env.ADVANCE_RATE * (3 + advanceMult))
        },
    },

