    special_dozka_knock: {
        slug: "special_dozka_knock",
        name: "Flood",
        type: 'special+autohit+self',
        anim: "",
        usage: {
            act: "unfamiliar shapes writhe beyond the threshold",
        },

        details: {
            flavor: `'utilize dull leverage to throw the misguided off-balance'`,
            onUse: "'prepares delayed directional effect';'[STAT::kb] against foes'",
        },

        stats: {
            kb: 3
        },

        strings: {
            telegraphName: "Spatial Bash",
            telegraphHelp: "<n-col definition='STATUS++kb'>KB::3</n-col> to all ALLY actors in specified direction",
        },

        autohit: true,
        avoidChaining: true,
        exec: function(user, target) {
            let directions = ["up", "down", "left", "right"]
            let direction = directions.sample({remove: true})
            
            setTimeout(() => {
                env.rpg.effectMessage.action({
                    user: user,
                    target: user,
                    reason: "dozkallvi",
                    action: `an impact impends!`,
                    specialHitText: `the team will be knocked <n-col>3 tiles (${direction.toUpperCase()})</n-col>!!`,
                    isMinor: true,
                    showFullDetail: true,
                })
            }, env.ADVANCE_RATE * 2)

            let tile = user.piece.tile
            tile.focusOnThisTile()
            play("okidoia")

            let effect = env.rpg.grid.createTileEffect({
                tiles: [tile],
                originTile: tile,
                effect: "telegraph",
                telegraphAnim: "heartbash",
                specialName: this.strings.telegraphName,
                specialHelp: this.strings.telegraphHelp,
                origin: user,
                length: 1,
                specialClass: `heartbash hb-${direction}`,
                data: {
                    rotation: (direction == "up" || direction == "down") ? "90" : "0",
                    strength: 3,
                    direction: direction,
                    onCreated: (effect) => {
                        effect.lineDraws = {}
                        effect.predictLineInterval = setInterval(()=>{
                            if(!env.rpg.active) clearInterval(effect.predictLineInterval);
                            env.rpg.allyTeam.members.forEach(m=>{ if(m?.piece?.tile) {
                                let tracedPath = m.piece.tile.traceDirection(direction, {ignoresActors: true})
                                let tracedPoint = tracedPath[Math.min(effect.data.strength, tracedPath.length - 1)]

                                if(!effect.lineDraws[m.slug] || effect.lineDraws[m.slug]?.closed || effect.lineDraws[m.slug]?.lastPoint !== m.piece.tile) {
                                    if(effect.lineDraws[m.slug]) effect.lineDraws[m.slug].close()
                                    effect.lineDraws[m.slug] = drawEffectLine(m, tracedPoint, { duration: 10000, angleDriftAmount: 0, effectClass: `knockwarn kw-${direction}${(tracedPath.length - 1) < effect.data.strength ? " short" : ""}`, color: m.team.name == "neutral" ? "neutral" : "friend"})
                                    effect.lineDraws[m.slug].lastPoint = m.piece.tile
                                }
                            }})
                        }, 500)
                    },
                    onDeleted: (effect) => { clearInterval(effect.predictLineInterval); effect.lineDraws && Object.values(effect.lineDraws).forEach(ld=>ld.close()) }
                },

                telegraphExec: (effect) => {
                    let affected = env.rpg.allyTeam.members.filter(m => m.piece)

                    affected.sort((a, b) => {
                        switch(direction) {
                            case "up": return a.piece.y - b.piece.y;
                            case "down": return b.piece.y - a.piece.y;
                            case "left": return a.piece.x - b.piece.x;
                            case "right": return b.piece.x - a.piece.x;
                            default: return 0;
                        }
                    })

                    affected.forEach(m => {
                        m.piece.knockback({
                            direction: direction,
                            strength: 3
                        })
                    })
                },
            })

            env.rpg.updatePropertyListeners({specificEl: effect.tiles[0].effectMap[effect.id].fx.firstElementChild, forceDirectAttribute: true})

            setTimeout(() => {
                advanceTurn(user)                
            }, env.ADVANCE_RATE * 4)
        },
    },

