    vekfight_frenzy: {
        slug: "vekfight_frenzy",
        name: "Furious Flurry",
        type: 'target',
        anim: "basic-attack",
        
        usage: {
            act: "%USER stabs at %TARGET",
            crit: "A FRIGHTENING BLOW",
            hit: "%TARGET's flesh distorts...",
            miss: "%TARGET EVADES"
        },

        details: {
            flavor: "'utilize sharpened limbs in agile flurry'",
            onUse: `'use this action up to three times on target';'cease on miss';'prepare follow-up attack'`,
            onHit: `'[STAT::amt] [STATUS::terror]'`,
            conditional: `<em>FOLLOW-UP::</em>'[STAT::additionalHP] [STATUS::terror]';'pull 1 step closer'`
        },

        aoe: {
            size: 0
        },

        stats: {
            range: 2,
            accuracy: 4,
            crit: 0.05,
            amt: 1,
            additionalHP: 2,
            kb: 1,
            status: {
                terror: {
                    name: 'terror',
                    length: 1
                }
            },
        },

        avoidChaining: true,
        exec: function(user, target, beingUsedAsync, {actionMessageIndex, reason} = {}) {
            let action = this
            if(!env.rpg.turnData[`${user.slug}-terrorstab-${actionMessageIndex}`]) env.rpg.turnData[`${user.slug}-terrorstab-${actionMessageIndex}`] = 0
            env.rpg.turnData[`${user.slug}-terrorstab-${actionMessageIndex}`]++
            if(!beingUsedAsync) delayAdvance(1500)

            return env.GENERIC_ACTIONS.singleTarget({
                action, 
                user, 
                target,
                hitSfx: {
                    name: 'stab',
                    rate: 1
                },
                genExec: ({target}) => {
                    if(reason || beingUsedAsync) return;
                    setTimeout(() => {
                        env.rpg.effectMessage.action({
                            user: user,
                            target: user,
                            reason: env.STATUS_EFFECTS.story_vekoa.name,
                            status: env.STATUS_EFFECTS.story_vekoa,
                            action: `%USER prepares a wide strike...`,
                            isMinor: true,
                            showFullDetail: true,
                        })    
                    }, 400)

                    play("okidoia")

                    let tiles = env.rpg.grid.markTiles({
                        originTile: user?.piece?.tile,
                        shape: "plus",
                        size: 4,
                        ignoresObstacles: true,
                        ignoresLOS: true,
                        includesOrigin: true
                    })
        
                    let effect = env.rpg.grid.createTileEffect({
                        tiles, 
                        effect: "telegraph",
                        origin: user,
                        telegraphAnim: "telegraph",
                        telegraphFor: "heart_tendril_pull",
                        originTile: user?.piece?.tile,
                        specialRenderEffect: "originTile",
                        telegraphTargets: "foes",
                        specialClass: `plus`,
                        data: {
                            size: 4
                        },
                        originTile: user?.piece?.tile,
                        anchorType: "actor",
                        anchorActor: user,
                    })  
                },
                hitExec: ({target}) => {
                    if(target.piece && user.piece) target.piece.knockback({
                        direction: user?.piece?.tile.getRelativeDirection(target?.piece?.tile), 
                        strength: 1
                    })

                    if(!beingUsedAsync) addStatus({target, status: this.stats.status.terror.name, length: this.stats.status.terror.length, origin: user})

                    if(env.rpg.turnData[`${user.slug}-terrorstab-${actionMessageIndex}`] < 2 && target.hp > 0) {
                        setTimeout(()=>{
                            reactDialogue(user, `frenzy`)
                            user.piece.teleportToTile(user.piece.tile.pathfindTo(target.piece.tile, {towards: true}).path.pop(), {follow: true})
                            useAction(user, this, target, {beingUsedAsync: true, actionMessageIndex, reason: this.name})
                        }, env.ADVANCE_RATE * 0.5)
                    }
                }
            })
        }
    },

