    kivskin_malfunction: {
        slug: "kivskin_malfunction",
        name: "Wild Swing",
        type: 'special',
        anim: "skitter",
        autohit: true,
        usage: {
            act: "%USER swings about uncontrollably!"
        },
        details: {
            flavor: "'briefly lose control of movement'",
            onUse: `'HIT between 1-3 random actors'`,
            onHit: `'[STAT::amt]'`,
            onCrit: `'[STATUS::stun]'`
        },
        stats: {
            accuracy: 0.75,
            crit: 0.2,
            amt: 2,
            status: {
                stun: {
                    name: 'stun',
                    length: 1
                }
            },
        },
        exec: function(user, target, beingUsedAsync, {actionMessageIndex} = {}) {            
            let action = this
            let possibleActors = env.rpg.turnOrder.filter(a => a != user && a.state != "dead")
            let actors = []
            let count = rand(1, 4)
            removeStatus(user, "windup") // this can be used in place of archival smash by accident

            for (let i = 0; i < count && possibleActors.length > 0; i++) {
                actors.push(possibleActors.sample({remove: true}))
            }

            setTimeout(() => {
                env.rpg.effectMessage.action({
                    user: user,
                    target: target,
                    reason: "destabilize",
                    action: `%USER malfunctioned!`,
                    status: env.STATUS_EFFECTS.destabilized,
                    isMinor: true
                })
            }, env.ADVANCE_RATE * 0.25)

            sendFloater({
                target: user,
                type: "arbitrary",
                specialClass: "fate",
                arbitraryString: "MALFUNCTION",
                size: 2
            })

            env.GENERIC_ACTIONS.teamWave({
                arbitraryActorList: actors,
                exec: (actor, i) => {
                    env.GENERIC_ACTIONS.singleTarget({
                        action, 
                        user, 
                        target: actor,
                        critStatus: this.stats.status.stun,
                        genExec: ({target, hit}) => {
                            env.rpg.effectMessage.action({
                                user: user,
                                target,
                                hit: true,
                                action: this.usage.act,
                                specialHitText: hit ? `%USER's wild swings hit %TARGET!` : `%USER's wild swings miss %TARGET!`,
                                actionMessageIndex,
                            })      
                        }
                    })
                },
                extraDelay: 400,
                advanceAfterExec: true, beingUsedAsync, user,
            })
        },

        enemyUsageIf: (actor) =>  hasStatus(actor, "destabilized")
    },

