    repairfriend_salvage: {
        slug: "repairfriend_salvage",
        name: "Salvage",
        type: 'special',
        anim: "basic-attack",
        usage: {
            act: "%USER TENDS TO THE GOLEM",
        },

        details: {
            flavor: "'apply repairs to powerful golem nearby'",
            onUse: `'[STAT::amt] [STAT::amtBP] [STATUS::repairs] [STATUS::carapace]'`,
            conditional: `<em>DESTABILIZED</em>::'50% chance to fail heal';'apply [STATUS::million_teeth] instead of repairs'\n<em>GOLEM DEAD</em>::'restore subject golem to 10%HP';'no other effect'</em>`
        },

        stats: {
            autohit: true,
            amt: -4,
            amtBP: 2,
            status: {
                repairs: { name: 'repairs', length: 1},
                million_teeth: { name: 'million_teeth', length: 1},
                carapace: { name: 'carapace', length: 1 },
            },
        },

        exec: function(user, target, beingUsedAsync, {actionMessageIndex} = {}) {    
            let realTarget = user.team.members.find(m=>m.slug == "wounded_archival_golem")
            if(!realTarget) return setTimeout(()=>advanceTurn(user), env.ADVANCE_RATE * 1.5);

            if(realTarget.state == "dead") {
                play('mend', 0.5)
                realTarget.hp = Math.floor(target.maxhp * 0.1)
                combatRevive(realTarget)
                reactDialogue(realTarget, 'receive_rez')
            
                env.rpg.effectMessage.action({
                    user: user,
                    target: realTarget,
                    hit: true,
                    action: this.usage.act,
                    specialHitText: `%TARGET rises, barely functional...`,
                    actionMessageIndex,
                })

                addStatus({target: realTarget, status: "stun", origin: user, length: 1})

            } else {
                play('mend', 1)
                combatHit(realTarget, {amt: this.stats.amtBP, beneficial: true, type: "barrier", origin: this.affecting, runEvents: false, autohit: true})

                let destabilized = hasStatus(user, "destabilized")
                if(!destabilized && Math.random() > 0.5) combatHit(realTarget, {amt: this.stats.amt, beneficial: true, origin: this.affecting, runEvents: false, autohit: true})
                addStatus({target: realTarget, status: destabilized ? "million_teeth" : "repairs", origin: user, length: 1})
                addStatus({target: realTarget, status: "carapace", origin: user, length: 1})
            
                env.rpg.effectMessage.action({
                    user: user,
                    target: realTarget,
                    hit: false,
                    action: this.usage.act,
                    specialHitText: destabilized ? `%TARGET's repair is imperfect...` : `%TARGET is repaired further!`,
                    actionMessageIndex,
                })

                if(destabilized) {
                    setTimeout(() => {
                        env.rpg.effectMessage.action({
                            user: user,
                            target: user,
                            reason: "destabilize",
                            action: `%USER malfunctioned!`,
                            status: env.STATUS_EFFECTS.destabilized,
                            isMinor: true
                        })
                    }, env.ADVANCE_RATE * 0.25)

                    sendFloater({
                        target: user,
                        type: "arbitrary",
                        specialClass: "fate",
                        arbitraryString: "MALFUNCTION",
                        size: 2
                    })
                }
            }

            setTimeout(()=>advanceTurn(user), env.ADVANCE_RATE * 1.5)
        },
    },

