    /* FRAME ing rework. the framing rework. the... the frame Ingrework... */
    /* new versions of old actions, which will remain above until I'm sure we can just cut them */

    sacrifice_utility: { // the original granted access to a restore, this one will naturally restore any dead allies
        slug: "sacrifice_utility",
        name: "Sacrifice",
        type: 'self+autohit+support+focus',
        anim: "wobble",
        usage: {
            act: "%USER PREPARES FOR DESPERATE MEASURES"
        },
        details: {
            flavor: "'empowers next action greatly'",
            onUse:`'[STATUS::empowered] [STATUS::evasion]'`,
            conditional: `<em>SACRIFICE::</em>'absorb one negative status from each ally'\n<em>REVIVE::</em>'HIT self for [STAT::amt] per <n-col>DOWN</n-col> ally to restore them with [STAT::healHP]'`
        },

        stats: {
            healHP: -5,
            amt: 2,
            status: {
                evasion: {
                    name: 'evasion',
                    length: 2
                },
                empowered: {
                    name: 'empowered', // now just gives empowered, which is buffed
                    length: 1
                }
            },
        },
        
        exec: function(user, target) {
            play("talkchoir7", 2)
            addStatus({target: user, status: "evasion", length: 2, noReact: true})
            addStatus({target: user, status: "empowered", length: 1, noReact: true})

            user.team.members.forEach((m, i)=>{
                setTimeout(()=>{
                    if(m.state == "dead" && m != user) {

                        m.hp = hasStatus(user, "destabilized") ? 10 : 5
                        combatRevive(m)
                        reactDialogue(m, 'receive_rez')

                        setTimeout(() => {
                            env.rpg.effectMessage.action({
                                user: user,
                                target: m,
                                reason: "sacrifice",
                                action: `%USER's sacrifice restores their allies!`,
                                specialHitText: `%TARGET rises to their feet!`,
                                showFullDetail: true,
                                isMinor: true
                            })

                            combatHit(user, {amt: 2, autohit: true, redirectable: false, ignoreMods: true, origin: user, dontDrawEffectLine: true})
                        }, env.ADVANCE_RATE * 0.2)
                    } else if(m != user) {
                        let negativeStatuses = m.statusEffects.filter(s=>!s.beneficial && !s.infinite && !s.passive)
                        if(negativeStatuses.length > 0) {
                            let statusToRemove = negativeStatuses.sample()
                            removeStatus(m, statusToRemove.slug)

                            play("talkchoir", 3)
                            addStatus({target: user, status: statusToRemove.slug, length: statusToRemove.duration, dontDrawIconLine: true})
                            drawEffectLine(m.box, user.box, {
                                color: "friend",
                                effectClass: "baseline icon thick componentline component-ichor",
                                duration: 1500,
                                style: `--icon: url(${statusToRemove.icon || `/img/sprites/combat/statuses/${statusToRemove.slug}.gif`})`
                            })

                            env.rpg.effectMessage.action({
                                user: user,
                                target: m,
                                reason: "sacrifice",
                                action: `%USER bears a new burden...`,
                                specialHitText: `%TARGET's ${statusToRemove.name} is transferred to %USER!`,
                                showFullDetail: true,
                                isMinor: true
                            })
                        }
                    }
                }, i * (env.ADVANCE_RATE * 0.25))
            })
            
            return 'nothing'
        },

        avoidChaining: true
    },

