        help: () => `${env?.rpg?.is2D ? "<f-col>+1 MOVEMENT</f-col>\n" : ''}vastly reduces chance of being HIT and CRIT<n-col class='shiftdetail'>\n(-90% IN:ACC% & IN:CRIT%)</n-col>`,
        removes: ["vulnerable"],
        opposite: "vulnerable",
