        strings: {
            madnessRedirect: `%USER's madness sends their action awry!`,
            newTarget: `%TARGET becomes their new target!`,
        },
        
        events: {
            onBeforeAction: function(context) {
                if(!hasStatus(this.status.affecting, "terror")) {
                    removeStatus(this.status.affecting, "madness")
                    return
                }

                if(!context.settings.action.type.includes("target")) return;
                
                // alter target maybe
                if(Math.random() < 0.5) {
                    //select from whole turnorder
                    let subject = context.user
                    let oldTarget = context.settings.target
                    let newTarget = env.rpg.turnOrder.filter(actor=>actor.state != "dead" && actor.state != "lastStand" && actor.slug != oldTarget.slug)
                    if(newTarget.length) {
                        newTarget = newTarget.sample()
                    } else return;

                    console.log("old target was", context.settings.target, "new target is", newTarget)

                    context.settings.target = newTarget

                    drawEffectLine(this.status, subject, {
                        color: "dark",
                        effectClass: "baseline icon fear",
                        duration: 3000,
                        style: `--icon: url(${this.status.icon})`
                    })

                    setTimeout(()=>{                            
                        env.rpg.effectMessage.action({
                            user: subject,
                            target: newTarget,
                            reason: this.status.name,
                            action: this.status.strings.madnessRedirect,
                            specialHitText: this.status.strings.newTarget,
                            isMinor: true,
                            showFullDetail: true,
                            status: this.status,
                        })
                    }, env.ADVANCE_RATE * 0.25)
                }
            },

            onRemoveStatus: function({target, removingStatusName}) {
                if(removingStatusName == "terror") removeStatus(this.status.affecting, "madness")
            },
        }
