    spikes: {
        slug: "spikes",
        name: "Spikes",
        help: "consume all <n-col definition='STATUS++spikes'>T:SPIKES</n-col> <n-col>when struck</n-col> and return <o-col>-t:HP</o-col>\nfails if inverted, removed or <n-col>DOWNed</n-col> by attack\n<span class='minorstate'>does not decay</span>",
        tickType: "special",
        beneficial: "complex",
        opposite: "siphon",
        removes: ["siphon"],
        icon: "/img/sprites/combat/statuses/spikes.gif",
        strings: {
            skewer: `%USER's spikes skewer their attacker!`,
            pierce: `%TARGET is pierced for [amt]HP!`,
        },
        events: {
            onCombatHit: function({subject, origin, attack, initialAmt, runEvents, beneficial, damageClass}) {
                if(
                    env.rpg.turnData[`${this.status.affecting.id}-preppingspike`] ||
                    !origin ||
                    beneficial ||
                    initialAmt <= 0 || // if it doesn't deal damage
                    this.status.affecting.team.members.includes(origin) ||
                    damageClass == "evade" ||
                    !runEvents // i don't think we get here if this is true but just in case
                ) return;

                env.rpg.turnData[`${this.status.affecting.id}-preppingspike`] = true
                let returnDmg = this.status.duration

                //space for fate alteration when i get to that
                
                if(this.status.affecting.sprite) this.status.affecting.sprite.classList.add('skitter')
                setTimeout(()=>{
                    if(this.status.affecting.state != "living" || hasStatus(this.status.affecting, "siphon") || !hasStatus(this.status.affecting, "spikes")) {
                        if(this.status.affecting.sprite) this.status.affecting.sprite.classList.remove('skitter')
                        return
                    }

                    env.rpg.effectMessage.action({
                        user: this.status.affecting,
                        target: origin,
                        reason: this.status.name,
                        action: this.status.strings.skewer,
                        specialHitText: this.status.strings.pierce.replace("[amt]", returnDmg),
                        isMinor: true,
                        combineLikeAction: true,
                        status: this.status,
                    })

                    drawEffectLine(this.status.affecting, origin, {
                        color: "dark",
                        effectClass: "baseline icon thick mega spiked",
                        duration: 3000,
                        style: `--icon: url(${this.status.icon})`
                    })

                    if(this.status.affecting.sprite) this.status.affecting.sprite.classList.remove('skitter')

                    if(hasStatus(this.status.affecting, "fated_bone")) { // only halve if you have fated bone
                        this.status.duration -= Math.floor(Math.max(this.status.duration * 0.5, 1))
                        updateStats({actor: this.status.affecting})
                    } else removeStatus(this.status.affecting, "spikes")

                    env.rpg.turnData[`${this.status.affecting.id}-preppingspike`] = false
                    combatHit(origin, {amt: returnDmg, autohit: true, crit: 0, origin: false, redirectable: false, runEvents: false, origin: this.status.affecting})
                }, env.ADVANCE_RATE * 0.05)
            },
        }
    },

