    counter: { // ing addition
        slug: "counter",
        name: "Counter",
        beneficial: true,
        paintable: true,
        delayFirstTickForActorsOnTheRight: true,
        tickType: "onTurnEnd",
        icon: "/img/sprites/combat/statuses/counter.gif",
        help: () => `when attacked, use primary action on attacker${env.rpg?.is2D ? `\nblocks <n-col definition='STATUS++kb'>knockback</n-col> from counterable attacks` : ""}\n<span class='minorstate'>removed by <o-col definition='STATUS++stun'>STUN</o-col></span>`,
        
        events: {
            onBeforeCombatHit: function(context) {
                if(
                    !env.rpg.is2D ||
                    env.rpg.turnData[`${this.status.affecting.id}-countered`] ||
                    !context.origin ||
                    context.beneficial ||
                    context.amt <= 0 || // if it doesn't deal damage
                    context.initialTarget != this.status.affecting ||
                    this.status.affecting.team.members.includes(context.origin) ||
                    context.origin?.untargetable
                ) return;

                this.status.knockmod = -999
            },

            onCombatHit: function({subject, origin, attack, initialAmt, runEvents, beneficial}) {
                if(
                    env.rpg.turnData[`${this.status.affecting.id}-countered`] ||
                    !origin ||
                    beneficial ||
                    initialAmt <= 0 || // if it doesn't deal damage
                    subject != this.status.affecting ||
                    this.status.affecting.team.members.includes(origin) ||
                    subject.untargetable ||
                    !runEvents // i don't think we get here if this is true but just in case
                ) return;

                let primary = env.ACTIONS[this.status.affecting.actions[0]]

                //counter only works if your primary is within range of the origin
                if(env.rpg.is2D) {
                    let range = primary?.stats?.range || primary.range || 1
                    let dist = this.status.affecting.piece.getActorDistance({actors: [origin]})[0]
                    if(dist.rawDistance > range) return;
                    
                    sendFloater({ // floaters are also only called in 2D
                        target: this.status.affecting,
                        type: "arbitrary",
                        arbitraryString: "COUNTER!",
                        beneficial: false,
                        size: 0.75
                    })
                }

                if(this.status.affecting.sprite) this.status.affecting.sprite.classList.add('skitter')
                if(this.status.affecting.box) this.status.affecting.box.classList.add('skitter')
                
                env.rpg.turnData[`${this.status.affecting.id}-countered`] = true
                env.rpg.lastUpdate = Date.now() + 2000
                setTimeout(()=>{
                    if(this.status.affecting.state != "living" || hasStatus(this.status.affecting, "stun")) {
                        if(this.status.affecting.sprite) this.status.affecting.sprite.classList.remove('skitter')
                        if(this.status.affecting.box) this.status.affecting.box.classList.remove('skitter')
                        return
                    } 

                    drawEffectLine(this.status.affecting, origin, {
                        color: this.status.affecting.team.name == "neutral" ? "friend" : "obesk",
                        effectClass: "baseline icon thick mega",
                        duration: 3000,
                        style: `--icon: url(${this.status.icon})`
                    })

                    if(this.status.affecting.sprite) this.status.affecting.sprite.classList.remove('skitter')
                    if(this.status.affecting.box) this.status.affecting.box.classList.remove('skitter')
                    useAction(this.status.affecting, primary, origin, {reason: "counter", triggerActionUseEvent: false, beingUsedAsync: true, incitingStatus: this.status, importantActionMessage: true})
                }, env.ADVANCE_RATE * 0.5)
            },

            GLOBAL_onTurnEnd: function() {
                this.status.knockmod = 0
            }
        },
    },

