        icon: "/img/sprites/combat/statuses/surge.gif",
        events: {
            onTurn: function() { 
                reactDialogue(this.status.affecting, 'surge') 
                delete this.status.justGotSurge
            },
            
            onAction: function({user, action, target, beingUsedAsync}) {
                console.log("checking surge condition", 
                    action.noRepeat,
                    this.status.justGotSurge,
                    this.status.usedAction,
                    beingUsedAsync,
                    ["incoherent_", "steer", "floor", "windup", "intrusive"].some(slugpart => action.slug.includes(slugpart))
                )
                if(action.noRepeat || this.status.justGotSurge || this.status.usedAction || beingUsedAsync || ["incoherent_", "steer", "floor", "windup", "intrusive"].some(slugpart => action.slug.includes(slugpart))) return;
                let actionSettings = {reason: "surge", triggerActionUseEvent: false, beingUsedAsync: true, incitingStatus: this.status, importantActionMessage: true}

                //only do it this way in 1d combat
                if(!env.rpg.is2D) {
                    setTimeout(()=>{
                        drawEffectLine(user, target, {
                            color: "neutral",
                            effectClass: "baseline icon thick",
                            duration: 3000,
                            style: `--icon: url(${this.status.icon})`
                        })
                        
                        useAction(user, action, target, actionSettings)
                    }, 0.5 * env.ADVANCE_RATE)
                    removeStatus(this.status.affecting, "surge")
                } else {
                    this.status.usedAction = true
                    setTimeout(()=>{
                        drawEffectLine(user, target, {
                            color: "neutral",
                            effectClass: "baseline icon thick",
                            duration: 1000,
                            style: `--icon: url(${this.status.icon})`
                        })

                        if(action.aoe && target?.piece) env.rpg.grid.handleActionAOE({originActor: user, targetTile: target.piece.tile, action, actionSettings})
                        else useAction(user, action, target, actionSettings)
                    }, 0.25 * env.ADVANCE_RATE)
                }
            },

            onCreated: function({statusObj}) {
                if(statusObj.slug == this.status.slug) this.status.justGotSurge = true
            },

            onTurnEnd: function() {
                if(this.status.usedAction) removeStatus(this.status.affecting, "surge")
            }
        },
        help: "use next active action twice<span class='minorstate shiftdetail'>\ndoes not consume item charges when reusing item actions</span>"
