    fated_claws: {
        slug: "fated_claws",
        name: "FATED::Claws",
        passive: true,
        beneficial: true,
        icon: "/img/sprites/combat/passives/fated_claws.gif",
        impulse: { type: "fated", component: "claws" },
        help: `Action-retriggering impulses and effects may chain\n<n-col>Per CLAWS humor in shell::</n-col>\n- +7.5% chance to repeat HITS <span class='minorstate'>(self-triggering)</span>`,
        strings: {
            ambition: `%USER's ambition is unstoppable!`,
            rend: `%TARGET is rended again!`,
        },
        
        events: {
            onBeforeAction: function(context) { 
                context.triggerActionUseEvent = true
            },

            onCreated: function({statusObj}) {
                if(
                    statusObj.slug != this.status.slug ||
                    !this.status.affecting?.member?.components
                ) return;
                
                this.status.power = 0
                if(this.status.affecting?.member?.components) for (const [slotName, slotContents] of Object.entries(this.status.affecting.member.components)) {
                    if(slotContents == "claws") this.status.power++
                }

                if(this.status.affecting?.member?.augments) for (const augmentSlug of this.status.affecting.member.augments) {
                    let augment = env.ACTOR_AUGMENTS.generic[augmentSlug]
                    if(augment?.component) if(augment.component[1] == "claws") this.status.power += 2
                }
            },

            
            onHit: function({subject, origin, attack, beneficial, initialAmt}) {
                if(beneficial || origin.team.name == subject.team.name || subject.state == "dead") return;

                if(subject.state != "dead" && this.status.power && initialAmt != 0) {
                    if(!env.rpg.turnData.fatedClawsHits) env.rpg.turnData.fatedClawsHits = 0
                    env.rpg.turnData.fatedClawsHits++

                    let repeatChance = 0.075 * this.status.power
                    console.log("fated claws repeat chance:", repeatChance)
                    if(Math.random() < repeatChance) {
                        setTimeout(()=>{
                            combatHit(subject, {amt: initialAmt, origin, autohit: true, runEvents: true})

                            drawEffectLine(this.status, subject, {
                                color: "dark",
                                effectClass: "baseline icon componentline component-claws",
                                duration: 1500,
                                style: `--icon: url(${this.status.icon})`
                            })        
                            
                            play("stab", 0.75, 0.5)
                            
                            env.rpg.effectMessage.action({
                                user: origin,
                                target: subject,
                                reason: this.status.name,
                                action: this.status.strings.ambition,
                                specialHitText: this.status.strings.rend,
                                showFullDetail: true,
                                isMinor: true,
                                status: this.status,
                            })
                        }, Math.max((env.ADVANCE_RATE * 0.5) - env.rpg.turnData.fatedClawsHits * (env.ADVANCE_RATE * 0.05), 20))
                    }
                }
            },
        },
    },

