    bomb_volatile: {
        slug: "bomb_volatile",
        name: "Volatile",
        help: `\n<n-col>on direct IED hit or <o-col definition="STATUS++bomb">BOMB</o-col> detonation</n-col>,\ncreate permanent <o-col>CHEMICAL FIRE</o-col> tile effect<o-col class="shiftdetail">\n-20% MAX HP/turn</o-col>\n<o-col definition="STATUS++bomb">BOMB</o-col> charges increase radius once`,
        infinite: true,
        beneficial: "complex",
        persist: true,
        passive: true,
        incomingMult: -100,
        incomingToHit: 100,
        icon: "/img/sprites/combat/statuses/volatile.gif",

        detonate: function(target, status, size) {
            removeStatus(target, "bomb_volatile")
            let tiles = env.rpg.grid.markTiles({
                originTile: target.piece.tile,
                includesOrigin: true,
                size: size || 1
            })

            let explosiveTargets = tiles.map(t=>t?.piece?.actor).filter(a=>a && a != target)

            target.hp = 0
            if(target.base.slug == "destructible_spineroot") target.statusEffects[0].trigger()
            updateStats({actor: target})
            play("dull", 1.5)

            env.rpg.grid.createTileEffect({
                tiles: tiles,
                originTile: target.piece.tile,
                effect: "chemical_fire",
                origin: target,
            })

            if(explosiveTargets.length) env.GENERIC_ACTIONS.teamWave({
                arbitraryActorList: explosiveTargets,
                extraDelay: env.rpg.is2D ? 0 : 100,
                exec: (actor, i) => {
                    if(env?.rpg?.is2D) { // knockback in 2D!
                        if(actor.piece) actor.piece.knockback({ 
                            direction: actor?.piece?.tile.getRelativeDirection(status.tileEffect.originTile, true), 
                            strength: 5
                        })
                    }
                },
                advanceAfterExec: false
            })
        },
        
        events: {
            onCreated: function({statusObj}) {
                if(
                    statusObj.slug != this.status.slug ||
                    !this?.status?.affecting?.piece
                ) return;

                this.status.tileEffect = env.rpg.grid.createTileEffect({
                    tiles: [this.status.affecting.piece.tile], 
                    originTile: this.status.affecting.piece.tile,
                    effect: "firebomb",
                    anchorType: "actor",
                    anchorActor: this.status.affecting,
                    length: 1,
                    origin: this.status.origin,
                    telegraphAnim: "bombboom",
                    telegraphExec: (effect) => {
                        console.log("detonating bomb with effect", effect, effect.tiles, effect.tileRelativity)
                        this.status.detonate(this.status.affecting, this.status, this.status.tileEffectSize)
                    },
                })

                this.status.tileEffect.status = this.status
            },

            onActedUpon: function({user, action, target, beingUsedAsync, hit}) {
                if(!["cavik_attack_disruption", "scene_cavik_attack"].includes(action.slug) || !hit) return;
                this.status.tileEffect.infinite = false
                this.status.tileEffect.length = 0
                env.rpg.grid.advanceTileEffect(this.status.tileEffect)
            },

            onDeath: function() {
                this.status.tileEffect.infinite = false
                this.status.tileEffect.length = 0
                env.rpg.grid.advanceTileEffect(this.status.tileEffect)
            },

            onAddStatus: function({target, statusObj}) {
                if(statusObj.slug != "bomb" || this.status.affecting.state == "lastStand") return;
                if(this.status?.tileEffectSize > 1 && !env.rpg.unlimitedVolatileGrow) return;
                if(!this.status.tileEffectSize) this.status.tileEffectSize = 1
                this.status.tileEffectSize++
                
                let fxEl = this.status.tileEffect.originTile.effectMap[this.status.tileEffect.id].fx.firstChild
                let currentSize = Number(fxEl.style.getPropertyValue("--size").replace("%", ""))
                this.status.tileEffect.intendedSize = `${currentSize + 200}%`
                fxEl.style.setProperty("--size", this.status.tileEffect.intendedSize)  

                env.setTimeout(()=>
                    env.rpg.effectMessage.action({
                        user: statusObj.origin,
                        target: this.status.affecting,
                        status: this.status,
                        reason: this.status.name,
                        action: `%TARGET's volatility grows!`,
                        showFullDetail: true
                    }), 
                100)              
            }
        }
    },

