                        midCombatActorAdd(env.rpg.enemyTeam, "vekqou_stabber")
                        midCombatActorAdd(env.rpg.enemyTeam, "vekqou_support")

                        updateStats()
                        vfx({type: "flash", state: false, delay: 1000})
