    // ing items
    item_restorative: {  
        slug: "item_restorative",
        name: "Restoratives",
        passive: true,
        passiveClass: "item",
        beneficial: true,
        grantsActions: ["restore"], 
        icon: "/img/sprites/combat/passives/restoratives.gif",
        strings: {
            selfRez: `%USER hastily applied a restorative to stay standing! ([amt] restores remain)`,
            repairs: `%USER conducts repairs on %TARGET...`,
            rezCall: `SELFREZ`
        },
            
        //passive focus effect displayed in 2D
        extraAOE: {
            repairRangeWhenYouHoverOverFocus: {
                origin: "self",
                size: 2,
                shape: 'square',
                addClass: "beneficial",
                includesOrigin: true,
                showIf: (actor, target, action) => action.type.includes("focus")
            },

            repairRangeWhenActuallyTargeting: {
                origin: "target",
                size: 2,
                shape: 'square',
                addClass: "beneficial",
                includesOrigin: true,
                showIf: (actor, target, action) => action.type.includes("focus")
            },
        },

        help: `gain 3 uses of <n-col definition='ACTION++restore'>RESTORE</n-col>\nif <n-col>DOWN</n-col>, automatically use on self\n<n-col>focusing</n-col> heals<n-col class='shiftdetail'> (+1HP <f-col definition='STATUS++regen'>+1T:REGEN</f-col>)</n-col> lowest HP ally\n<span class='minorstate'>disabled after expending RESTORE</span>`,
                
        events: { 
            onCreated: function({statusObj}) {
                if(statusObj.slug == "item_restorative" && !this.status.initialized) {
                    this.status.initialized = true
                    if(this.status.affecting?.team?.name == "enemy") this.status.affecting.restorativeCount = 1 // to limit enemy rez frustration
                    else this.status.affecting.restorativeCount = 3 
                    this.status.affecting.lastStand = "restoratives"
                }
            },

            onLastStand: function() {
                if(this.status.affecting.restorativeCount > 0 && this.status.affecting.state == "lastStand") { // check again in case caught by another status
                
                    drawEffectLine(this.status, this.status.affecting, {
                        color: "friend",
                        effectClass: "baseline icon",
                        duration: 3000,
                        style: `--icon: url(${this.status.icon})`
                    })

                    this.status.affecting.restorativeCount--
                    console.log("restorative lastStand triggered, remaining count:", this.status.affecting.restorativeCount)      
                    let action = useAction(this.status.affecting, env.ACTIONS.restore, this.status.affecting, {
                        triggerActionUseEvent: false, 
                        beingUsedAsync: true, 
                        reason: this.status.name,
                        incitingStatus: this.status,
                    })
                    
                    addStatus({target: this.status.affecting, origin: this.status.affecting, status: "evasion", length: 2, noReact: true}); 
                    addStatus({target: this.status.affecting, origin: this.status.affecting, status: "regen", length: 3, noReact: true}); 

                    if(this.status.affecting.restorativeCount <= 0) {
                        this.status.affecting.lastStand = false
                        this.status.passiveIconElement.classList.add('disabled')
                    }

                    sendFloater({
                        target: this.status.affecting,
                        type: "arbitrary",
                        specialClass: "ichor",
                        arbitraryString: this.status.strings.rezCall,
                        size: 2
                    })

                    setTimeout(() => {
                        env.rpg.effectMessage.action({
                            user: this.status.affecting,
                            target: this.status.affecting,
                            actionMessageIndex: action.i,
                            reason: this.status.name,
                            action: this.status.strings.selfRez.replace("[amt]", this.status.affecting.restorativeCount),
                            specialHitText: this.status.strings.selfRez.replace("[amt]", this.status.affecting.restorativeCount),
                            isMinor: true,
                            showFullDetail: true,
                            status: this.status,
                        })                        
                    }, env.ADVANCE_RATE * 0.25)

                // weird edge case handling - last stand somehow persisted when it shouldn't have
                } else if(this.status.affecting.state == "lastStand" && (this.status.affecting.lastStand == "restoratives" || !this.status.affecting.lastStand)) {
                    this.status.affecting.lastStand = false
                    useAction(this.status.affecting, env.ACTIONS.restore, this.status.affecting, {
                        triggerActionUseEvent: false, 
                        beingUsedAsync: true, 
                        reason: this.status.name,
                        incitingStatus: this.status,
                    })
                }
            },

            onAction: function({user, action, target}) {
                if(action.slug == "restore" && this.status.affecting.restorativeCount == 0) {
                    this.status.affecting.lastStand = false
                    this.status.passiveIconElement.classList.add('disabled')
                }

                if(action.type.includes("focus") && this.status.affecting.restorativeCount) {
                    setTimeout(()=>{
                        let target
                        let valid = user.team.members
                        if(env.rpg?.is2D) {
                            valid = env.rpg.grid.markTiles({originTile: user.piece.tile, size: 2, pleaseReturn: "actors", includesOrigin: true}).filter(t => t.team.name == user.team.name)
                        }

                        valid = valid.filter(m => m.state != "dead" && m.hp > 0)

                        if(valid.every(m => m.hp == m.maxhp)) target = valid.sample()
                        else target = valid.reduce((lowest, member) => (member.hp / member.maxhp) < (lowest.hp / lowest.maxhp) ? member : lowest)

                        if(!target || !target?.box) return; // this should never happen but the world is a magical place

                        addStatus({target, origin: user, status: "regen", length: 1, dontDrawEffectLine: true, noReact: true})
                        combatHit(target, {amt: -1, beneficial: true, type: "hp", autohit: true, origin: user})
                    
                        drawEffectLine(this.status, target, {
                            color: "friend",
                            effectClass: "baseline icon",
                            duration: 3000,
                            style: `--icon: url(${this.status.icon})`
                        })

                        setTimeout(() => {
                            env.rpg.effectMessage.action({
                                user: this.status.affecting,
                                target,
                                reason: this.status.name,
                                action: this.status.strings.repairs,
                                isMinor: true,
                                showFullDetail: true,
                                status: this.status,
                            })                        
                        }, env.ADVANCE_RATE * 0.25)
                    }, env.rpg.is2D ? (env.ADVANCE_RATE * 0.1) : 0)
                }
            },
        },
    },

