        slug: "item_kavruka",
        name: "Explosives",
        passive: true,
        passiveClass: "item",
        beneficial: true,
        icon: "/img/sprites/combat/passives/kavruka_satchel.gif",
        grantsActions: ["special_attack_all", "scene_kavruka"],
        strings: {
            draw: `%USER pulls an explosive kavruka from their satchel...`,
        },
            
        //passive crit effect is displayed in 2D under certain circumstances
        extraAOE: {
            explosionRange: {
                origin: "target",
                size: 2,
                shape: 'square',
                addClass: "explosivefollowup",
                includesOrigin: true,
                showIf: (actor, target, action) => !action.beneficial && (action.crit || action?.stats?.crit) && (action.amt || action?.stats?.amt)  && target
            }
        },
                
        events: { 
            onCreated: function({statusObj}) {
                if(statusObj.slug == "item_kavruka" && !this.status.initialized) {
                    this.status.initialized = true
                    this.status.affecting.kavrukaDrawn = false
                    this.status.affecting.kavrukasLeft = 3
                    this.status.affecting.kavrukaLimited = true       
                }
            },

            onCrit: function({subject, origin, attack, beneficial}) {
                let user = this.status.affecting
                if((!this.status.affecting.kavrukasLeft && !this.status.affecting.kavrukaDrawn) || beneficial || user.team.members.includes(subject) || user.state == "dead" || Math.random() > 0.75 || env.rpg.turnData[`${user.id}-kavruka`]) return;
                env.rpg.turnData[`${user.id}-kavruka`] = true
                
                if(env.rpg?.is2D) delayAdvance(env.ADVANCE_RATE * 0.3)
                setTimeout(()=>{
                    let targets = user.enemyTeam.members
                    if(env.rpg?.is2D) {
                        if(!subject?.piece?.tile) return;
                        targets = env.rpg.grid.markTiles({originTile: subject.piece.tile, size: 2, pleaseReturn: "actors", includesOrigin: true}).filter(t => t.team.name != user.team.name)
                    }

                    let wave = () => env.GENERIC_ACTIONS.teamWave({
                        arbitraryActorList: targets,
                        canHitDead: true, // as a treat
                        exec: (target, i)=>{
                            if(target.untargetable) return;
                            let actionUse = ()=> useAction(user, env.ACTIONS['kavruka_followup'], target, {triggerActionUseEvent: false, beingUsedAsync: true, reason: this.status.name, incitingStatus: this.status, force: true, importantActionMessage: true, sceneAnim: true})

                            if(!env.rpg.is2D) actionUse()
                            else if(target.piece) env.rpg.grid.handleAnim('tinyboom', actionUse,
                            {
                                origin: user, targetTile: target.piece.tile
                            })
                            
                        }
                    })
                    
                    if(!env.rpg.is2D) wave()
                    else env.rpg.grid.handleAnim('bombtoss', wave, {
                        origin: user, targetTile: subject.piece.tile, action: env.ACTIONS['kavruka_followup']
                    })

                }, env.ADVANCE_RATE * 0.25)
            },

            onAction: function({user, action, target}) {
                if(action.type.includes("focus") && !user.kavrukaDrawn && user.kavrukasLeft > 0) {
                    user.kavrukasLeft--
                    user.kavrukaDrawn = true

                    if(user.kavrukasLeft == 0) this.status.passiveIconElement.classList.add('disabled')
                
                    drawEffectLine(this.status, user, {
                        color: "friend",
                        effectClass: "baseline icon",
                        duration: 3000,
                        style: `--icon: url(${this.status.icon})`
                    })

                    setTimeout(() => {
                        env.rpg.effectMessage.action({
                            user: this.status.affecting,
                            target: this.status.affecting,
                            reason: this.status.name,
                            action: this.status.strings.draw,
                            isMinor: true,
                            showFullDetail: true,
                            status: this.status,
                        })                        
                    }, env.ADVANCE_RATE * 0.25)
                }
            },
        },

