    story_veilklight: {
        slug: "story_veilklight",
        name: "Odd Light",
        help: `misusing minor dull connectivity`,
        icon: "/img/sprites/combat/passives/anomalous_light.gif",
        passive: true,
        beneficial: true,
        infinite: true,

        strings: {
            granting: `\ngranting <f-col definition="STATUS++%STATUSSLUG">+%STATUSAMTT:%STATUSNAME</f-col> to <o-col>%TARGET</o-col> on turn`,
            generalHelp: `<span class="minorstate">\nbehavior altered when destabilized</span>`,
            castLight: `%USER's light casts strange colors`,
            regen: `%TARGET's flesh continuously repairs itself...`,
            empowered: `%TARGET's limbs continuously sharpen...`,
            focused: `%TARGET's reactions seem quicker...`,

        },

        events: {
            onCreated: function({statusObj}) {
                if(statusObj.slug == this.status.slug) {
                    //each grants a different status
                    this.status.grantingTarget = !page.party.crittamode ? env.rpg.turnOrder.find(a=>hasStatus(a, "story_attendant")) : this.status.affecting.team.members.filter(m=>!m.base.slug.includes("personnel_veilklight")).sample()
                    let initializedCount = this.status.affecting.team.members.filter(member => hasStatus(member, "story_veilklight")).length
                    this.status.grantingStatus = (initializedCount % 2) ? "regen" : "focused"

                    if(!this.status.grantingTarget) this.status.grantingTarget = this.status.affecting // hard fallback if last one before starting support
     
                    env.rpg.effectMessage.action({
                        user: this.status.affecting,
                        target: this.status.grantingTarget,
                        reason: this.status.name,
                        action: this.status.strings.castLight,
                        isMinor: true,
                        specialHitText: this.status.grantingStatus == "regen" ? this.status.strings.regen : this.status.strings.focused,
                        status: this.status,
                    }) 

                    this.status.help += this.status.strings.granting
                        .replace("%STATUSNAME", this.status.grantingStatus.toUpperCase())
                        .replace("%STATUSAMT", this.status.grantingStatus == "regen" ? "2" : "1")
                        .replace("%STATUSSLUG", this.status.grantingStatus)
                        .replace("%TARGET", this.status.grantingTarget.name)
                    this.status.help += this.status.strings.generalHelp

                    this.status.icon = `/img/sprites/combat/passives/oddlight_${this.status.grantingStatus}.gif`
                    this.status.passiveIconElement.style.setProperty("--img", `url(${this.status.icon})`)
                    this.status.events.onTurn()
                }
            },
            
            onTurn: function() {
                if(this.status.grantingTarget?.removed || this.status.grantingTarget?.state == "dead" || !this.status.grantingTarget) {
                    if(page.party.crittamode) {
                        this.status.grantingTarget = this.status.affecting.team.members.filter(m=>!m.base.slug.includes("personnel_veilklight") && m.state != "dead").sample()
                        if(!this.status.grantingTarget) this.status.grantingTarget = this.status.affecting // hard fallback to self support
                    }
                        
                    
                    if(!this.status.grantingTarget) return;
                }

                addStatus({target: this.status.grantingTarget, origin: this.status.affecting, status: this.status.grantingStatus, length: this.status.grantingStatus == "regen" ? 2 : 1, noFloater: true, dontDrawIconLine: true})

                drawEffectLine(this.status, this.status.grantingTarget, {
                    color: "friend",
                    effectClass: "baseline icon thick mega",
                    duration: 3000,
                    style: `--icon: url(${this.status.icon})`
                })

                play('mend')
            }
        }
    },

