                    thisGuy.sprite.querySelector('.golemsprite-body').src = `/img/sprites/combat/foes/archivalgolem-body_damaged.gif`
                    thisGuy.sprite.querySelector('.golemsprite-arms').src = `/img/sprites/combat/foes/archivalgolem-arms_damaged.gif`
