    // a fucked up terror-like tiered status that combines most of the old malware item effects into one
    /* 
        - 1: REGEN instead becomes ROT
		- 2: double effects of damaging statuses
		- 3: being HIT inflicts 1T:OPEN_WOUND
		- 4: being HIT reduces positive statuses by 1T
		- 5: being HIT grants 1T:EMPOWERED to attacker
        - 6+: gain xT:ROT on turn where T is the intensity of MALWARE
    */
    malware: {
        slug: "malware",
        name: "Malware",
        tickType: "special",
        icon: "/img/sprites/combat/statuses/malware.gif",

        strings: {
            generalHeader: `sabotages function as intensity increases`,
            stage1: `<f-col definition="STATUS++regen">REGEN</f-col> becomes <o-col definition="STATUS++rot">ROT</o-col>`,
            stage2: `double effects of damaging statuses`,
            stage3: `<n-col>being HIT</n-col> inflicts <o-col definition="STATUS++vulnerability">1T:VULNERABILITY</o-col>`,
            stage4: `<n-col>being HIT</n-col> reduces positive statuses by 1T`,
            stage5: `<n-col>being HIT</n-col> grants <o-col definition="STATUS++empowered">2T:EMPOWERED</o-col> to attacker`,
            stage6: `<n-col>on turn</n-col>, gain <o-col definition="STATUS++rot">[[X]]T:ROT</o-col>`,
            generalFooter: `removed by DOWNing [[ORIGIN]]`,

            //generic so that it can be combined if multiple people are terrorized
            removal: `the malware dissipates...`,
            removalSpecific: `%TARGET feels way better!`,
        },

        help: `sabotages function as intensity increases\nremoved only by DOWNing origin`,
        helpGen: function() {
            console.log(this)
            let helpString = this.strings.generalHeader
            for(let i = 1; i <= Math.min(5, this.duration); i++) {
                helpString += `\n<o-col>STAGE ${i}:</o-col> ${this.strings[`stage${i}`]}`
            }

            if(this.duration >= 6) {
                helpString += `\n<o-col>STAGE 6+:</o-col> ${this.strings.stage6.replace('[[X]]', this.duration)}`
            }

            helpString += `\n${this.strings.generalFooter}`
            return helpString
        },

        events: { // ing todo - add effectmessages and stuff
            onCreated: function() { this.status.help = () => this.status.helpGen() }, //directly associates with this status instead of the window
            onTurn: function() { 
                if(this.status.duration >= 6) {
                    addStatus({target: this.status.affecting, origin: this.status.affecting, status: "rot", length: this.status.duration, dontDrawIconLine: true, noReact: true})
                }
            },

            onBeforeAddStatus: function(context) {
                if(context.status == "regen") {
                    context.status = "rot"

                    /*
                    drawEffectLine(this.status.passiveIconElement, this.status.affecting.box, {
                        color: "neutral",
                        effectClass: "baseline icon componentline component-light",
                        duration: 1500,
                        style: `--icon: url(${this.status.icon})`
                    })
                    
                    setTimeout(()=>{                            
                        env.rpg.effectMessage.action({
                            user: this.status.affecting,
                            target: this.status.affecting,
                            reason: this.status.name,
                            action: `%USER's carapace twists into brittle thorns...`,
                            isMinor: true,
                            status: this.status,
                        })
                    }, env.ADVANCE_RATE * 0.25)
                    */
                }
            },

            onStruck: function({subject, attack, initialAmt, beneficial}) { 
                if(
                    beneficial ||
                    subject.team.name == this.status.affecting.name ||
                    initialAmt <= 0
                ) return; // only trigger on harmful hits from enemies
                
                if(this.status.duration >= 3) {
                    addStatus({target: this.status.affecting, origin: this.status.affecting, status: "vulnerable", length: 1, dontDrawIconLine: true, noReact: true})
                }

                if(this.status.duration >= 4) {
                    env.GENERIC_ACTIONS.statusShift({target: this.status.affecting})
                }

                if(this.status.duration >= 5) {
                    addStatus({target: subject, origin: this.status.affecting, status: "empowered", length: 2, dontDrawIconLine: true, noReact: true})
                }
            },
            
            GLOBAL_onDeath: function({originalEventTarget}) {
                if(
                    originalEventTarget != this.status.origin
                ) return;

                removeStatus(this.status.affecting, this.status.slug)

                /*
                drawEffectLine(originalEventTarget?.box || this.status.passiveIconElement, this.status.affecting.box, {
                    color: "friend",
                    effectClass: "baseline icon componentline component-ichor",
                    duration: 1500,
                    style: `--icon: url(${this.status.icon})`
                })

                setTimeout(()=>{
                    env.rpg.effectMessage.action({
                        user: this.status.affecting,
                        target: this.status.affecting,
                        reason: this.status.name,
                        action: `%USER's confidence swells!`,
                        isMinor: true,
                        status: this.status,
                    })
                }, env.ADVANCE_RATE * 0.25)
                */
            },
        }
    },

