    // ichor
    aug_ichor_skivi: {
        slug: "aug_ichor_skivi",
        name: "Parasite",
        passive: true,
        beneficial: true,
        icon: "/img/sprites/combat/augs/parasite.gif",
        help: `<n-col>HITTING foes</n-col> with <o-col definition='STATUS++siphon'>SIPHON</o-col> or <o-col definition='STATUS++rot'>ROT</o-col> copies their negative statuses to other random foe with half duration`,
        strings: {
            spread: `%USER spreads [subject]'s afflictions!`,
            infection: `%TARGET is infected!`,
        },
        events: {
            onHit: function({subject, origin, attack, beneficial}) {
                if(
                    beneficial || 
                    origin.team.name == subject.team.name || 
                    subject.state == "dead" ||
                    (!hasStatus(subject, "siphon") && !hasStatus(subject, "rot"))
                ) return;

                let validTargets = origin.enemyTeam.members.filter(m => 
                    m != subject && 
                    m.state == "living" && 
                    !m.untargetable
                )

                if(!validTargets.length) return;
                let target = validTargets.sample()
                let copiedStatuses = []

                subject.statusEffects.forEach(status => {
                    if(
                        !status.beneficial && 
                        !status.passive && 
                        status.duration > 0
                    ) {
                        addStatus({target, origin, status: status.slug, length: Math.ceil(status.duration * 0.5), dontDrawIconLine: true, noReact: true})
                        copiedStatuses.push(status.name)
                    }
                })

                if(!copiedStatuses.length) return;
                drawEffectLine(subject, target, {
                    color: "obesk",
                    effectClass: "baseline icon componentline component-ichor",
                    duration: 1500,
                    style: `--icon: url(${this.status.icon})`
                })

                setTimeout(() => {
                    env.rpg.effectMessage.action({
                        user: origin,
                        target: target,
                        reason: this.status.name,
                        action: this.status.strings.spread.replace('[subject]', subject.name),
                        specialHitText: this.status.strings.infection,
                        isMinor: true,
                        status: this.status,
                    });
                }, env.ADVANCE_RATE * 0.25)
            }
        },
    }, 

    aug_ichor_tap: {
        slug: "aug_ichor_tap",
        name: "Undying",
        passive: true,
        beneficial: true,
        icon: "/img/sprites/combat/augs/parasite.gif",
        help: `VITAL TAP revives DOWNED allies\n<n-col>HITTING foes</n-col> with <o-col definition='STATUS++siphon'>SIPHON</o-col> or <o-col definition='STATUS++rot'>ROT</o-col> steals 5% of their HP<n-col class="shiftdetail">(MIN:1)</n-col>`,
        actionTip: `revives target ally before normal effects`,
        actionDefSpecialNotator: function (action, statMap, actor) {
            if(action.slug == "newmend_mega") {
                return `<bst-col>${this.name.toUpperCase()}::</bst-col>'${this.actionTip}'`
            }
        },
        strings: {
            vitality: `%USER extracts further vitality!`,
            steal: `%USER steals [amt]HP from %TARGET!`,
        },
        
        events: {
            onHit: function({subject, origin, attack, beneficial}) {
                if(
                    beneficial || 
                    origin.team.name == subject.team.name || 
                    subject.state == "dead" ||
                    (!hasStatus(subject, "siphon") && !hasStatus(subject, "rot"))
                ) return;

                let stolenHP = Math.max(1, Math.floor(subject.hp * 0.05))
                combatHit(subject, {amt: stolenHP, origin, autohit: true, redirectable: false, runEvents: false})
                combatHit(origin, {amt: -stolenHP, beneficial: true, origin, autohit: true, redirectable: false, runEvents: false})

                //we only draw the line if siphon isn't drawing a line already
                if(!hasStatus(subject, "siphon")) drawEffectLine(subject, origin, {
                    color: "friend",
                    effectClass: "baseline icon componentline component-ichor",
                    duration: 1500,
                    style: `--icon: url(${this.status.icon})`
                })

                setTimeout(() => {
                    env.rpg.effectMessage.action({
                        user: origin,
                        target: subject,
                        reason: this.status.name,
                        action: this.status.strings.vitality,
                        specialHitText: this.status.strings.steal.replace('[amt]', stolenHP),
                        isMinor: true,
                        status: this.status,
                    });
                }, env.ADVANCE_RATE * 0.25)
            }
        },
    }, 

    aug_ichor_sacrifice: {
        slug: "aug_ichor_sacrifice",
        name: "Overextend",
        passive: true,
        beneficial: true,
        icon: "/img/sprites/combat/augs/sacrifice.gif",
        help: `<n-col>on ally DOWN</n-col>, take 25% of their max HP as damage and revive them with that amount<n-col class="shiftdetail minorstate">\nif DOWNed by this effect, will not trigger until next turn</n-col>`,
        strings: {
            overextend: `%USER overextends to revive %TARGET!`,
        },

        events: {
            GLOBAL_onDeath: function({originalEventTarget}) {
                let subject = originalEventTarget
                let user = this.status.affecting

                if(
                    user.state == "dead" ||
                    user == subject || 
                    user.team.name != subject.team.name || 
                    subject.state != "dead" ||
                    env.rpg.turnData[`${user.slug}_overextend_death`] 
                ) return;

                setTimeout(()=>{

                    let damageAmt = Math.ceil(subject.maxhp * 0.25)
                    setTimeout(()=> {
                        combatRevive(subject)
                        combatHit(subject, {amt: (-damageAmt + 1 /* combatrevive sets it to 1 */), beneficial: true, origin: user, autohit: true, redirectable: false, runEvents: false})
                    }, env.ADVANCE_RATE * 0.05)

                    setTimeout(()=> {
                        combatHit(user, {amt: damageAmt, origin: subject, autohit: true, redirectable: false, runEvents: false})
                    }, env.ADVANCE_RATE * 0.1)

                    setTimeout(()=>{
                        if(user.state == "dead") env.rpg.turnData[`${user.slug}_overextend_death`] = true
                        play("mend", 5)
                        drawEffectLine(subject, user, {
                            color: "friend",
                            effectClass: "baseline icon componentline component-ichor",
                            duration: 1500,
                            style: `--icon: url(${this.status.icon})`
                        })

                        env.rpg.effectMessage.action({
                            user,
                            target: subject,
                            reason: this.status.name,
                            action: this.status.strings.overextend,
                            isMinor: true,
                            showFullDetail: true,
                            status: this.status,
                        })
                    }, env.ADVANCE_RATE * 0.11)

                }, env.ADVANCE_RATE * 0.05)
            }
        }
    }, 

