    aug_light_destabilize: { 
        slug: "aug_light_destabilize",
        name: "Natural Extreme",
        passive: true,
        beneficial: true,
        icon: "/img/sprites/combat/augs/massdestabilize.gif",
        help: `Granting <n-col definition="STATUS++destabilized">DESTABILIZED</n-col> doubles duration of all statuses on target`,
        strings: {
            alteration: `%USER alters the thoughtspace!`,
            stranger: `%TARGET grows stranger...`,
        },
        
        events: {
            onInflictStatus: function({target, statusObj, totalLength}) {
                if(
                    statusObj.slug != "destabilized"
                ) return;
                let origin = this.status.affecting

                target.statusEffects.forEach(status=>{
                    if(status.duration && 
                        !status.infinite && 
                        !status.passive && 
                        !status.noDouble &&
                        !(hasStatus(target, "enacting") && status.slug == "evasion")
                    ) {
                        status.duration *= 2
                        if(status.max && (status.duration > status.max)) status.duration = status.max
                    }
                })

                reactDialogue(origin, "laugh")

                drawEffectLine(this.status, target, {
                    color: "dark",
                    effectClass: "baseline icon componentline component-light",
                    duration: 3000,
                    style: `--icon: url(${this.status.icon})`
                })

                setTimeout(()=>{                            
                    env.rpg.effectMessage.action({
                        user: origin,
                        target: target,
                        reason: this.status.name,
                        action: this.status.strings.alteration,
                        specialHitText: this.status.strings.stranger,
                        isMinor: true,
                        status: this.status,
                    })
                }, env.ADVANCE_RATE * 0.25)
                
                updateStats({actor: target})
            },
        },
    },

