    specter_archival: {
        slug: "specter_archival",
        name: "Archival Apparition",
        help: `only pursues <o-col definition='STATUS++story_targeted'>targets</o-col>\nuses weaker strikes to gain <n-col definition='STATUS++windup'>windup</n-col>\nhighly resistant <n-col class='shiftdetail'>(-1 incoming damage, -2 KB, total stun immunity)</n-col> unless <o-col definition='STATUS++vulnerable'>VULNERABLE</o-col>\n<span class="minorstate">recklessly aggressive <n-col class='shiftdetail'>(+2 MOVEMENT & -50% accuracy)</n-col> while <n-col definition='STATUS++destabilized'>DESTABILIZED</n-col></span>`,
        icon: "/img/sprites/combat/passives/archival_apparition.gif",
        passive: true,
        beneficial: true,
        infinite: true,
        knockmod: -2,
        incomingFlat: -1,
        strings: {
            stagger: `%USER staggers!`,
            stunResist: `%USER resists the stun...`,
            flaw: "a flaw is revealed!",
            stunVuln: `%USER is vulnerable to stun!`,
            resisted: `%USER is hardly scratched`
        },
        events: {
            onAddStatus: function({target, statusObj}) {
                let update = false 

                switch(statusObj.slug) {
                    case "vulnerable":
                        delete this.status.incomingFlat
                        delete this.status.knockmod
                        update = true
                    break

                    case "destabilized":
                        this.status.outgoingToHit = -0.5
                        this.status.moveMod = 2
                        update = true
                    break
                }

                if(update) updateStats({actor: this.status.affecting})
            },

            onRemoveStatus: function({target, removingStatusName}) {
                let update = false
                switch(removingStatusName) {
                    case "vulnerable":
                        this.status.incomingFlat = -1
                        this.status.knockmod = -2
                        update = true
                    break

                    case "destabilized":
                        delete this.status.outgoingToHit
                        delete this.status.moveMod
                        update = true
                    break
                }

                if(update) updateStats({actor: this.status.affecting})
            },
            
            onBeforeAddStatus: function(context) {
                if(context.status == "stun" && !hasStatus(this.status.affecting, "vulnerable") && !hasStatus(this.status.affecting, "stun_immune")) {
                    context.noAdd = true

                    env.setTimeout(()=>
                        env.rpg.effectMessage.action({
                            user: this.status.affecting,
                            target: this.status.affecting,
                            reason: this.status.name,
                            action: this.status.strings.stagger,
                            specialHitText: this.status.strings.stunResist,
                            showFullDetail: true,
                            isMinor: true,
                            status: this.status
                        }), 
                    100)
                } else if(context.status == "vulnerable" && !hasStatus(this.status.affecting, "vulnerable")) {
                    env.setTimeout(()=> 
                        env.rpg.effectMessage.action({
                            user: this.status.affecting,
                            target: this.status.affecting,
                            reason: this.status.name,
                            status: this.status,
                            action: this.status.strings.flaw,
                            specialHitText: this.status.strings.stunVuln,
                            showFullDetail: true,
                            isMinor: true,
                        })
                    , 100)
                }
            },

            onStruck: function({subject, attack, initialAmt, beneficial}) { 
                if(
                    beneficial ||
                    !(attack == 0 && attack != initialAmt && initialAmt > 0)
                ) return; // we want to signal that this critter blocked you hardcore
                
                env.rpg.effectMessage.action({
                    user: this.status.affecting,
                    target: this.status.affecting,
                    reason: this.status.name,
                    action: hasStatus(this.status.affecting, "vulnerable") ? this.status.strings.flaw : this.status.strings.resisted,
                    showFullDetail: true,
                    isMinor: true,
                    status: this.status
                })
            }
        }
    },

