    aiming_directional: {
        slug: "aiming_directional",
        name: "Aiming",
        help: "acting in direction on next turn\navoid path to prevent damage\ninterrupted by stun",
        icon: "/img/sprites/combat/statuses/aiming_directional.gif",
        infinite: true,
        beneficial: "complex",
        events: {
            onCreated: function({statusObj}) {
                // necessitates a passing of 'data' in addStatus, with { direction, action }
                if(statusObj.slug != this.status.slug || this.status.initialized) return;
                if(!env?.rpg?.is2D) return;

                this.status.initialized = true
                this.status.action = this.status.data.action
                let initialTarget = this.status.affecting.piece.tile.traceDirection(this.status.data.direction, {teamFocus: this.status.data.teamFocus, ignoreSpecificTeam: this.status.data.ignoreTeam}).pop()

                if(!initialTarget) removeStatus(this.status.affecting.slug, this.status.slug);
                
                this.status.tileEffect = env.rpg.grid.createTileEffect({
                    tiles: [initialTarget], 
                    effect: "telegraph",
                    anchorType: "tile",
                    origin: this.status?.data?.origin || this.status.affecting,
                    telegraphFor: this.status.action, 
                    telegraphAnim: this.status?.data?.telegraphAnim || "telegraph_beam",
                    telegraphFrom: this.status?.data?.telegraphFrom || this.status.affecting,
                    noTelegraphFocus: this.status?.data?.noTelegraphFocus,
                    additionalTelegraphExec: this.status?.data?.additionalTelegraphExec,
                    specialClass: "aimed-at",
                    length: 1,
                })

                this.status.currentDestination = initialTarget

                this.status.lineInterval = setInterval(()=>{
                    if(this.status.tileEffect.ranTelegraph || !this.status?.affecting?.piece?.tile) {
                        clearInterval(this.status.lineInterval)
                        if(env.rpg.active) {
                            this.status.lastLine.close()
                            removeStatus(this.status.affecting, this.status.slug)
                        }
                        return
                    }

                    let tracedPath = this.status.affecting.piece.tile.traceDirection(this.status.data.direction, {teamFocus: this.status.data.teamFocus, ignoreSpecificTeam: this.status.data.ignoreTeam})
                    let tracedPoint = tracedPath[tracedPath.length - 1]

                    if(
                        !this.status?.lastLine?.closed && 
                        this.status.currentDestination == tracedPoint &&
                        this.status.lastHostPosition == this.status.affecting.piece.tile 
                    ) return;

                    if(this.status.lastLine) this.status.lastLine.close()

                    if(this.status.currentDestination != tracedPoint) {
                        this.status.currentDestination = tracedPoint
                        console.log("moving to position", this.status.currentDestination.x, this.status.currentDestination.y)
                        env.rpg.grid.moveTileEffect(this.status.tileEffect, {position: this.status.currentDestination})
                    }

                    this.status.lastHostPosition = this.status.affecting.piece.tile 
                    this.status.lastLine = drawEffectLine(this.status.affecting, this.status.currentDestination, { duration: 10000, angleDriftAmount: 0, effectClass: this.status?.data?.effectClass ? this.status?.data?.effectClass : `megabeam`, color: this.status.affecting.team.name == "ally" ? "friend" : "obesk"})
                }, env.ADVANCE_RATE * 0.5)
            },

            onAddStatus: function({target, statusObj}) {
                if(statusObj.slug == "stun") removeStatus(this.status.affecting, this.status.slug)
            },
            
            onDeath: function() {
                if(this.status.lastLine) this.status.lastLine.close()
                env.rpg.grid.deleteTileEffect(this.status.tileEffect)
                clearInterval(this.status.lineInterval)
            },

            onRemoveStatus: function({target, removingStatusName}) {
                if(removingStatusName == this.status.slug) {
                    if(this.status.lastLine) this.status.lastLine.close()
                    env.rpg.grid.deleteTileEffect(this.status.tileEffect)
                    clearInterval(this.status.lineInterval)
                }
            },
        }
    },

